const ranges={s1:[-30,30],s2:[0,100],s3:[0,1]};
const sql=["BEGIN;", "DELETE FROM readings;", "DELETE FROM events;"];
const lines=String(msg.payload).replace(/^\uFEFF/, '').split(/\r?\n/);
for (const raw of lines) {
 const parts=raw.trim().split(/\s+/), kind=parts.shift(); if (!kind) continue;
 const f=Object.fromEntries(parts.map(p=>p.split('='))); const n=Number(f.n);
 if (!Number.isInteger(n) || n<1) { node.error('Некорректный номер измерения: '+raw,msg); return null; }
 const t=n*2;
 if(kind==='DATA') for(const s of ['s1','s2','s3']) {
  const value=Number(f[s]); if(f[s]===undefined || !Number.isFinite(value)){node.error('Некорректное значение: '+raw,msg);return null;}
  sql.push(`INSERT INTO readings(n,t_s,sensor,value) VALUES(${n},${t},'${s}',${value});`);
  if(value<ranges[s][0] || value>ranges[s][1]) sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'FAULT','датчик ${s} вне диапазона');`);
 } else if(kind==='EVENT' && ['THRESHOLD','NORMAL'].includes(f.type)) sql.push(`INSERT INTO events(n,t_s,type,message) VALUES(${n},${t},'${f.type}','');`);
 else {node.error('Некорректная строка: '+raw,msg);return null;}
}
sql.push('COMMIT;'); msg.payload=sql.join('\n')+'\n'; return msg;
